insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"adjectives_basics_q01_finish","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q01_start","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q02_finish","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q02_start","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q03_finish","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q03_start","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q04_finish","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q04_start","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q05_finish","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q05_start","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q06_finish","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}},{"key":"adjectives_basics_q06_start","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"adjectives_basics_q01_finish","locale":"he","line_order":0,"content":"תראו את זה. הצבעים חזרו לציור, ועכשיו אפשר לראות את השמיים ואת העלים.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q01_finish","locale":"he","line_order":1,"content":"אבל העץ והציפור עדיין נראים אותו דבר בדיוק. חסרות לי מילים של גודל.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q01_start","locale":"he","line_order":0,"content":"שלום. אני הצייר של הממלכה, וקרה לי משהו מוזר. הציור הגדול שלי הפך אפור.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q01_start","locale":"he","line_order":1,"content":"בכל ציור יש שמות של דברים, כמו עץ או ציפור, ויש מילים שמספרות איך הדבר נראה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q01_start","locale":"he","line_order":2,"content":"מילת תיאור = adjective. היא מילה שמספרת איך משהו נראה, מה הצבע שלו או מה הגודל שלו.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q01_start","locale":"he","line_order":3,"content":"נתחיל מהצבעים. red = אדום, blue = כחול, green = ירוק, yellow = צהוב.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q01_start","locale":"he","line_order":4,"content":"האבן ליד העץ שומרת את המילים שנעלמו. בואו נחזיר אותן.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q02_finish","locale":"he","line_order":0,"content":"מצוין. עכשיו העץ גדול, הציפור קטנה, והציור מתחיל לחיות שוב.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q02_finish","locale":"he","line_order":1,"content":"יש לי בעיה אחת אחרונה. הכנתי שלטים לתערוכה וכל המילים בהם התבלבלו.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q02_finish","locale":"he","line_order":2,"content":"הילדה בפארק הוורדים מסדרת לי את השלטים. לכו אליה, היא תסביר לכם.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q02_start","locale":"he","line_order":0,"content":"בציור שלי יש עץ וציפור, ואי אפשר לדעת מי מהם גדול ומי קטן.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q02_start","locale":"he","line_order":1,"content":"big = גדול, small = קטן, tall = גבוה, long = ארוך.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q02_start","locale":"he","line_order":2,"content":"גם אלה מילות תיאור. הן לא אומרות מה הדבר, אלא איזה גודל יש לו.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q02_start","locale":"he","line_order":3,"content":"בואו נחזיר גם את המילים האלה לאבן.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q03_finish","locale":"he","line_order":0,"content":"יופי. עכשיו כל שלט נקרא נכון, והמילה המתארת תמיד עומדת בהתחלה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q03_finish","locale":"he","line_order":1,"content":"ציירתי כאן על השולחן כמה פנים בשביל התערוכה, ואי אפשר לדעת מה הן מרגישות.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q03_start","locale":"he","line_order":0,"content":"היי. אני עוזרת לצייר להכין שלטים לתערוכה, אבל המילים בשלטים עומדות בסדר לא נכון.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q03_start","locale":"he","line_order":1,"content":"בעברית אומרים קודם את שם הדבר ואחר כך את התיאור, למשל תפוח אדום.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q03_start","locale":"he","line_order":2,"content":"באנגלית זה הפוך. מילת התיאור עומדת לפני שם הדבר: a red apple.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q03_start","locale":"he","line_order":3,"content":"בואו נסדר את השלטים יחד על השולחן.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q04_finish","locale":"he","line_order":0,"content":"עכשיו רואים בדיוק מי שמח ומי עצוב. הציורים שלי נראים הרבה יותר אמיתיים.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q04_finish","locale":"he","line_order":1,"content":"נשאר רק דבר אחד. עדיין לא סיפרנו במשפט שלם איך כל דבר נראה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q04_start","locale":"he","line_order":0,"content":"הפנים שציירתי כאן על השולחן יצאו כולן אותו דבר, בלי חיוך ובלי דמעה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q04_start","locale":"he","line_order":1,"content":"גם לרגשות יש מילות תיאור. happy = שמח, sad = עצוב, angry = כועס, tired = עייף.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q04_start","locale":"he","line_order":2,"content":"בואו נכתוב ליד כל פנים את ההרגשה שלהן.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q05_finish","locale":"he","line_order":0,"content":"כל המשפטים מוכנים, ואתם כבר יודעים לספר איך כל דבר בתערוכה נראה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q05_finish","locale":"he","line_order":1,"content":"חזרו אל הצייר ליד העץ הגדול. הוא מחכה לסיים את הציור.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q05_start","locale":"he","line_order":0,"content":"אפשר לומר רק מילה אחת, אבל אפשר גם לבנות משפט שלם.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q05_start","locale":"he","line_order":1,"content":"העץ גבוה = The tree is tall. המילה is מחברת בין הדבר לבין התיאור שלו.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q05_start","locale":"he","line_order":2,"content":"כשמדברים על כמה דברים משתמשים ב-are: הציפורים קטנות = The birds are small.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q05_start","locale":"he","line_order":3,"content":"בואו נכתוב יחד את המשפטים לתערוכה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q06_finish","locale":"he","line_order":0,"content":"הציור שלם. כל עץ, כל ציפור וכל פנים קיבלו את המילים שלהם בחזרה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q06_finish","locale":"he","line_order":1,"content":"אתם יודעים עכשיו מה זו מילת תיאור, איפה היא עומדת באנגלית, ואיך בונים איתה משפט.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q06_finish","locale":"he","line_order":2,"content":"קחו את המטבעות האלה כתודה. התערוכה נפתחת בזכותכם.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q06_start","locale":"he","line_order":0,"content":"חזרתם בדיוק בזמן. נשאר לי חלק אחד בציור שעדיין אפור.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q06_start","locale":"he","line_order":1,"content":"הפעם צריך הכל יחד: צבעים, גדלים, רגשות ומשפט שלם.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_q06_start","locale":"he","line_order":2,"content":"בסוף תקבלו מהאבן את אבן הצבעים. הביאו לי אותה ואסיים את הציור.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
